// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// CHIMNEY STACK: a shaft with a smoking crown. The owner saw campfires perched on the very tip of a stack with a hay
// bale showing beside them. A chimney's fire sits INSIDE the flue: a crown one block wider than the shaft on every side
// covers the hay and the campfire on all four sides, and one more course of masonry rises above the fire, so the smoke
// comes out of a mouth and the fire itself is never seen from the side.
//   chimneyPlan({ x, z, size, base, top, material, band, fire, signal }) -> [[x, y, z, block, state], ...]
//   x, z: the shaft's north-west cell; size: the shaft's width (1 or 2, square); base: its lowest course;
//   top: the course the fire sits in (the crown is top-1 .. top+1, the slab cap at top+2).
//   material / band: { full, slab } (roofs.mjs materialOf). fire: false leaves the flue empty (a dead chimney).
// Layout (size 1, seen from the side):    cap   s s s        top+2: slab cap on the crown ring, the flue open
//                                          rim   # . #        top+1: masonry all round the open flue
//                                          fire  # f #        top  : campfire walled on all four sides
//                                          hay   = h =        top-1: hay walled on all four sides (band course)
//                                          shaft   #          ...  : the shaft, down to base
const AIR = ["air", undefined];

export function chimneyPlan({ x, z, size = 1, base, top, material, band = material, fire = true, signal = true }) {
  const out = [], n = Math.max(1, size), hay = top - 1, rim = top + 1, cap = top + 2;
  const inShaft = (cx, cz) => cx >= x && cx < x + n && cz >= z && cz < z + n;
  const isFlue = (cx, cz) => cx === x && cz === z;               // the fire burns in the north-west shaft cell
  for (let cx = x; cx < x + n; cx++) for (let cz = z; cz < z + n; cz++) for (let y = base; y < hay; y++) out.push([cx, y, cz, material.full, undefined]);
  for (let cx = x - 1; cx <= x + n; cx++) for (let cz = z - 1; cz <= z + n; cz++) {
    const ring = !inShaft(cx, cz);
    for (const y of [hay, top, rim]) {
      if (isFlue(cx, cz) && fire) {
        if (y === hay) out.push([cx, y, cz, signal ? "hay_block" : material.full, signal ? { axis: "y" } : undefined]);
        else if (y === top) out.push([cx, y, cz, "campfire", { lit: "true", signal_fire: String(!!signal), facing: "north", waterlogged: "false" }]);
        else out.push([cx, y, cz, ...AIR]);
      } else if (isFlue(cx, cz) && y !== hay) out.push([cx, y, cz, ...AIR]);
      else out.push([cx, y, cz, y === hay ? band.full : material.full, undefined]);
    }
    if (ring) out.push([cx, cap, cz, material.slab, { type: "bottom", waterlogged: "false" }]);
  }
  return out;
}
